exports.main = async () => {
  const existing = await db.collection('ingredient_preset').count();
  if (existing.total > 0) return { skipped: true, already: existing.total };
  let added = 0;
  for (let i = 0; i < DOCS.length; i += 100) {
    const batch = DOCS.slice(i, i + 100);
    await db.collection('ingredient_preset').add({ data: batch });
    added += batch.length;
  }
  return { added, total: DOCS.length };
};
